partintro.section:
&reftitle.classsynopsis;
#[\AllowDynamicProperties] stdClass
यो class मा कुनै पनि methods वा default properties हुँदैनन्।

   &reftitle.examples;

    object मा typecasting गर्दा सिर्जना भएको


<?php
$obj = (object) array('foo' => 'bar');
var_dump($obj);


    &example.outputs;


object(stdClass)#1 (1) {
  ["foo"]=>
  string(3) "bar"
}




    json_decode को नतिजा स्वरूप सिर्जना भएको


<?php
$json = '{"foo":"bar"}';
var_dump(json_decode($json));


    &example.outputs;


object(stdClass)#1 (1) {
  ["foo"]=>
  string(3) "bar"
}




    dynamic properties declare गर्ने तरिका


<?php
$obj = new stdClass();
$obj->foo = 42;
$obj->{1} = 42;
var_dump($obj);


    &example.outputs;


object(stdClass)#1 (2) {
  ["foo"]=>
  int(42)
  ["1"]=>
  int(42)
}
